"Cada cambio es un golpe de energía. Sois un equipo de 22.":"Every change is a jolt of energy. You're a 22-man team.",
"Cada desventaja tiene su ventaja. Con menos dinero, tenemos más hambre. Y el hambre gana más partidos que el oro.":"Every disadvantage has its advantage. With less money, we're hungrier. And hunger wins more games than gold.",
"Cada día se nota más lo que vale {name}. Otro gol y van {goals}. ¡CRACK!":"Every day you see more what {name} is worth. Another goal, that's {goals}. CLASS!",
"Cada día un reto. Pero sufrir es parte del trabajo. Quien no sufre no sabe lo que vale volver a jugar.":"Every day a challenge. But suffering is part of the job. If you don't suffer, you don't know what it's worth to play again.",
"Cada etapa de tu mascota tiene su propio dibujo: cuando crezca, quizá tengas que volver a colocarlos.":"Each stage of your pet has its own drawing: when it grows, you may need to place them again.",
"Cada jugador rinde al 100 % en su posición.":"Every player performs at 100% in their own position.",
"Cada mal partido se compara con las leyendas. La presión se nota.":"Every bad game gets compared to the legends. You feel the pressure.",
"Cada ojeador te trae informes al empezar cada tramo. Con más estrellas, el potencial que ves es más fiable; con más viajes, encuentra más jugadores.":"Each scout brings you reports at the start of every stage. More stars make the potential you see more reliable; more travel finds more players.",
"Cada partido es historia. Los jóvenes aprenden de ti.":"Every match is history. The youngsters learn from you.",
"Cada partido peor que el anterior. ¿Qué estamos haciendo?":"Every game worse than the last. What are we doing?",
