"Comunicas que no renovarás. El míster te manda a la grada hasta nuevo aviso.":"You say you won't renew. The manager sends you to the stands until further notice.",
"Comunicas que quieres buscar minutos fuera.":"You say you want to look for minutes elsewhere.",
"Con calma. He visto muchas de estas, y lo único que importa es no cambiar nada. Ni el menú.":"Calm. I've seen plenty of these, and all that matters is not changing anything. Not even the menu.",
"Con calma. Un derbi se gana con la cabeza más que con las piernas. Y yo, hoy, tengo muy buena cabeza.":"Calmly. A derby is won with the head more than the legs. And today, my head is in great shape.",
"Con diez el {club} es más simpático. Gracias, {name} 🤝":"{club} are much nicer with ten men. Thanks, {name} 🤝",
"Con diez en el campo desde el minuto 10, tampoco se podía hacer más. El árbitro tiene que explicárselo a la gente.":"With ten men from the 10th minute, there wasn't much more we could do. The referee has to explain it to the fans.",
"Con el 'siuuu' de siempre. No me preguntéis dónde me lo enseñaron, pero me sale solo.":"With the usual 'siuuu'. Don't ask me where I learned it, it just comes out.",
"Con el estómago revuelto. Y no sé cómo lo hace Ferguson desde hace años: yo me muero.":"With my stomach in knots. I don't know how Ferguson has done it for years: it's killing me.",
"Con el juvenil ({comp}): {n} partidos y {cs} porterías a cero.":"With the youth team ({comp}): {n} matches and {cs} clean sheets.",
"Con el juvenil ({comp}): {n} partidos, {g} goles y {a} asistencias.":"With the youth team ({comp}): {n} matches, {g} goals and {a} assists.",
"Con el premio recién recibido, la prensa te reclama.":"With the award freshly won, the press wants a word.",
"Con ese nivel de {name}, mejor que entre otro, de verdad.":"With {name} at that level, better to bring someone else on, honestly.",
"Con hambre. Hambre de títulos, hambre de ganar. A quien no tenga hambre le invito a ver el partido desde la grada.":"Hungry. Hungry for titles, hungry to win. Anyone who isn't hungry is welcome to watch from the stands.",
"Con humildad. Mañana ya pensamos en el siguiente.":"With humility. Tomorrow we're already thinking about the next one.",
"Con la cabeza alta. Llegar hasta aquí ya dice mucho de este grupo.":"Heads held high. Getting this far says a lot about this group.",
"Con la cabeza fría, decides seguir luchando.":"With a cool head, you decide to keep fighting.",
"Con la llegada de {name}, el {club} suma calidad. Habrá que ver cómo encaja en el grupo.":"With {name} arriving, {club} add quality. We'll see how he fits into the group.",
"Con la moral alta, tus jugadores rinden más.":"With high morale, your players perform better.",
"Con la sub-21":"With the U21s",
"Con lo que cuesta su banquillo nos pagamos la temporada entera. Y ojo, que nos sobra ilusión.":"What their bench costs would pay for our whole season. But watch out, we've got hunger to spare.",
"Con lo que ha pasado hoy, probablemente sí. No tiene sentido mentir. Habría que ganarlo todo, y eso es difícil.":"After today, probably yes. No point lying. We'd have to win everything, and that's hard.",
"Con lo que tengo, voy a pelear. Y si ganamos, que nadie me pregunte por fichajes. Y si perdemos, tampoco.":"I'll fight with what I have. And if we win, nobody ask me about signings. If we lose, same.",
