"El candidato gana las elecciones gracias a tu nombre. En verano tendrás su oferta sobre la mesa… y en tu club ya te llaman traidor.":"The candidate wins the election thanks to your name. In the summer you'll have his offer on the table… and at your club they already call you a traitor.",
"El candidato pierde y el precontrato sale a la luz. Pasas de ídolo a sospechoso.":"The candidate loses and the pre-contract comes to light. You go from idol to suspect.",
