"Encararte con él":"Confront him",
"Encargar un estudio a los analistas":"Commission a study from the analysts",
"Encerrarse":"Park the bus",
"Encerrarse atrás nunca sale bien. Gracias por nada, {name} 🙄":"Parking the bus never works. Thanks for nothing, {name} 🙄",
"Encerrarse y Defensiva: encajas menos, pero creas poco.":"Park the bus and Defensive: you concede less, but create little.",
"Encerrarte con la plantilla":"Lock yourself in with the squad",
"Encerrarte en el trabajo":"Bury yourself in work",
"Enchufado":"Switched on",
"Encontronazo en el entreno":"Training ground clash",
"Enero de 1995: Éric Cantona, recién expulsado, respondió con una patada de kung-fu a un aficionado del Crystal Palace que le insultaba. Le cayeron ocho meses de sanción.":"January 1995: Éric Cantona, just sent off, responded with a kung-fu kick to a Crystal Palace fan who was abusing him. He was handed an eight-month ban.",
"Enero de 2009: Rafa Benítez leyó en rueda de prensa una lista de «hechos» contra Alex Ferguson. El Manchester United acabó ganando aquella Premier.":"January 2009: Rafa Benítez read out a list of \"facts\" against Alex Ferguson at a press conference. Manchester United ended up winning that Premier League.",
"Enero de 2019: Marcelo Bielsa admitió haber espiado los entrenamientos de sus rivales con el Leeds. La liga inglesa multó al club con 200 000 libras.":"January 2019: Marcelo Bielsa admitted spying on his rivals' training sessions with Leeds. The English league fined the club £200,000.",
"Enhorabuena al {club}. Qué envidia, qué rabia, qué ganas de ganar el siguiente 😤👏":"Congrats to {club}. So jealous, so annoyed, so keen to win the next one 😤👏",
"Ensayarlo antes en un partido menor":"Rehearse it first in a smaller match",
"Enseñarle los datos en privado":"Show him the data in private",
"Enseñarle un truco":"Teach it a trick",
"Entiendes al míster: más minutos.":"You understand the manager: more minutes.",
