"Entra de {pos}":"On at {pos}",
"Entra mucho dinero. La grada protesta y algunos jugadores se sienten incómodos.":"Lots of money comes in. The fans protest and some players feel uncomfortable.",
"Entrada":"Tackling",
"Entrada a ras de suelo":"Sliding tackle",
"Entrada media":"Average ticket",
"Entras como un ciclón y das una asistencia. El míster toma nota.":"You come on like a whirlwind and set up a goal. The manager takes note.",
"Entre 2000 y 2003 el Real Madrid fichó cada verano a una gran estrella (Figo, Zidane, Ronaldo, Beckham): la era de los «galácticos».":"Between 2000 and 2003 Real Madrid signed a major star every summer (Figo, Zidane, Ronaldo, Beckham): the era of the \"Galácticos\".",
"Entre risas, el vestuario se convierte en una piña indestructible.":"Amid the laughs, the dressing room becomes an unbreakable unit.",
"Entregarte al plan":"Commit to the plan",
"Entrena 10 temporadas.":"Manage for 10 seasons.",
