"Entrenador específico de porteros":"Specialist goalkeeping coach",
"Entrenador gritando de rabia con el bolígrafo en la mano. Bolígrafo: roto. Pizarra: vacía. 🖊️":"Manager screaming in fury, pen in hand. Pen: broken. Whiteboard: empty. 🖊️",
