"Entrenar a los chavales del colegio":"Coach the school kids",
"Entrenar con el filial para coger ritmo":"Train with the reserves to build rhythm",
"Entrenar con él por tu cuenta":"Train with him on your own",
"Entrenar igual":"Train anyway",
"Entrenar te despeja. Poco a poco vuelve la chispa.":"Training clears your head. Little by little the spark returns.",
"Entrevista con tu pareja":"Interview with your partner",
"Entrevistas, marcas y redes: más seguidores y más fama cada tramo.":"Interviews, brands and socials: more followers and more fame every stage.",
"Enviar un burofax pidiendo salir":"Send a formal notice asking to leave",
"Enviar un informe a la federación":"Send a report to the federation",
"Envíalos a una región: traerán jugadores de esa zona que encajan en tus necesidades.":"Send them to a region: they'll bring back players from that area who fit your needs.",
"Equilibrada":"Balanced",
"Equilibrada es la opción segura si no sabes qué hacer.":"Balanced is the safe option if you're not sure what to do.",
"Equilibrado":"Balanced",
"Equilibrio entre progresión y descanso.":"A balance between development and rest.",
