"Estar a su lado":"Be there for him",
"Estar en el parto aunque te pierdas el partido":"Be at the birth even if you miss the match",
"Estar entre los nominados ya es histórico. Disfrutemos del momento.":"Being among the nominees is already historic. Let's enjoy the moment.",
