"Esto es fútbol. A veces ganas, a veces pierdes y a veces tu hermano te quita el postre. Así es.":"That's football. Sometimes you win, sometimes you lose and sometimes your brother steals your dessert. That's life.",
"Esto es para quienes no creyeron y para los que sí. Y para un servidor, que lo merecía como nadie.":"This is for those who didn't believe and for those who did. And for yours truly, who deserved it like no one else.",
"Esto es una MASACRE. {opp} se va a casa llorando 😭 #{club}":"This is a MASSACRE. {opp} are going home in tears 😭 #{club}",
"Esto no es una dictadura. Yo he dado la cara, que otros den la suya. Pero no voy a dimitir.":"This isn't a dictatorship. I've faced the music; let others face theirs. But I'm not resigning.",
"Estonia":"Estonia",
"Estos son tus jugadores. Toca cualquier nombre para cambiarlo, o genera otra plantilla si no te convence.":"These are your players. Tap any name to change it, or generate another squad if you're not convinced.",
"Estoy bien. Es solo un golpe. Mañana me hacen pruebas, pero si dependiera de mí, jugaba el domingo con una pierna.":"I'm fine. Just a knock. I've got tests tomorrow, but if it were up to me I'd play Sunday on one leg.",
"Estoy centrado en recuperarme. Lo demás es ruido. Y yo, con las muletas, hago mucho ruido propio.":"I'm focused on recovering. The rest is noise. And with my crutches, I make plenty of noise of my own.",
"Estoy en racha y quiero más. Que se preparen los porteros.":"I'm on a roll and I want more. Keepers had better watch out.",
"Estoy guardando lo mejor para cuando más se necesite.":"I'm saving my best for when it's needed most.",
"Estoy trabajando las salidas y los balones aéreos con el preparador. Se va a notar.":"I'm working on coming off my line and on crosses with the goalkeeping coach. You'll see the difference.",
