"Estudiarlo hasta la madrugada":"Study it into the small hours",
"Estudias a tus rivales al detalle. Llegas a los partidos sabiéndote cada movimiento.":"You study your opponents in detail. You go into games knowing their every move.",
"Estudio a cada delantero: cómo golpea, hacia dónde mira. Nada es casualidad.":"I study every striker: how they strike it, where they look. Nothing is by chance.",
