"Estáis en la recta final de la {cup}. El míster te avisa: si llegáis a los penaltis, te cambiará por el portero suplente, que es un especialista.":"You're in the home stretch of the {cup}. The manager warns you: if it goes to penalties, he'll swap you for the backup goalkeeper, who's a specialist.",
"Estáis justo por encima del descenso, empatados a puntos. ¿Os preocupa mirar hacia abajo?":"You're just above the drop zone, level on points. Are you worried looking over your shoulder?",
"Estáis {pos}º, en descenso y a {gap} de la salvación. ¿Temes por la categoría?":"You're #{pos}, in the drop zone and {gap} from safety. Do you fear relegation?",
"Estáis {pos}º, en descenso, aunque empatados con quien marca la salvación. ¿Temes por la categoría?":"You're #{pos}, in the drop zone, though level with the team just above it. Do you fear relegation?",
"Estáis {pos}º, en puestos de ascenso, con {gap} de margen sobre el {rival}. ¿Firmáis subir ya?":"You're #{pos}, in the promotion places, {gap} clear of {rival}. Would you sign for promotion now?",
"Estáis {pos}º, en puestos europeos, con {gap} de margen sobre el {rival}. ¿Es Europa el objetivo?":"You're #{pos}, in the European places, {gap} clear of {rival}. Is Europe the goal?",
"Están dejándolo todo en el campo. Esto es lo que quiero ver siempre 👏":"They're leaving everything on the pitch. This is what I always want to see 👏",
