"Horas antes de la gala del Balón de Oro te llega el soplo: no vas a ganar, quedarás {pos}. En el {club} proponen no viajar a París en señal de protesta.":"Hours before the Ballon d'Or gala you get a tip-off: you won't win, you'll finish {pos}. At {club} they suggest not travelling to Paris in protest.",
