"Hoy digo adiós, pero no al fútbol. Gracias por todo. Ha sido un sueño 💙":"Today I say goodbye, but not to football. Thanks for everything. It's been a dream 💙",
"Hoy el estadio ha sido un volcán. ¡Remontadón ante el {opp}! 🌋":"The stadium was a volcano today. Massive comeback against {opp}! 🌋",
