"Hoy ha sido una vergüenza absoluta. Me devuelven la entrada o qué 😡":"Today was an absolute disgrace. Do I get a refund or what 😡",
"Hoy ha sido uno de los días más especiales de mi vida. Gracias a todos por el cariño 🇪🇸🥹":"Today was one of the most special days of my life. Thanks to everyone for the love 🇪🇸🥹",
"Hoy la grada vibra. Esto sí es sentir el escudo. ¡Vamos {club}! 🎶":"The stands are rocking today. This is what the badge means. Come on {club}! 🎶",
"Hoy me he quedado sin palabras. {name} se ha salido con ese triplete 🔥":"I'm speechless today. {name} was on fire with that hat-trick 🔥",
"Hoy nace una leyenda. Recordad este día: debut de {name} ⚽":"A legend is born today. Remember this day: {name}'s debut ⚽",
"Hoy no es día de hablar. Lo siento.":"Today isn't a day for talking. Sorry.",
"Hoy no fue el día de {name}, pero hay que seguir confiando. Todos tenemos una mala tarde.":"Not {name}'s day, but we have to keep believing. We all have a bad afternoon.",
"Hoy no habrá comentarios, solo cervezas. Y las pagan los que dudaron de nosotros desde agosto.":"No comments today, just beers. And they're on those who doubted us since August.",
"Hoy no hay trabajo, hoy no hay estudios, hoy HAY DERBI GANADO 🥇":"No work today, no studying today, today WE WON THE DERBY 🥇",
"Hoy no se trabaja. Hoy se celebra. ¡{trophy} para el {club}! 🎊":"No work today. Today we celebrate. {trophy} for {club}! 🎊",
"Hoy vendería mi casa para ver otro partido como este. ¡Qué nivel! 🏠➡️🏟️":"I'd sell my house today to see another game like this. What a level! 🏠➡️🏟️",
"Hoy {me} se ha comido a {him}. Que no se hable más. 🔥":"Today {me} ate {him} alive. End of discussion. 🔥",
"Hoy {name} ha sido nuestro mejor jugador (del {opp}), gracias por tanto 😂":"Today {name} was our best player (for {opp}), thanks for everything 😂",
"Hoy, un poquito más cerca. Lo que no ganamos es el aplauso: eso lo reservo para el final de temporada.":"Today, a little bit closer. What we haven't earned is applause: I'm saving that for the end of the season.",
"Hubo secador de pelo. Y un par de platos volando. Pero lo que pasa en el vestuario se queda en el vestuario.":"There was a hairdryer. And a couple of flying plates. But what happens in the dressing room stays in the dressing room.",
"Hubo una discusión, sí. Era necesaria. A veces los vestuarios necesitan que alguien alce la voz.":"There was an argument, yes. It was needed. Sometimes dressing rooms need someone to raise their voice.",
