"La derrota no es el problema. El problema es no saber a qué juegas. El {club} tiene que encontrarse.":"Losing isn't the problem. The problem is not knowing how you want to play. {club} need to find themselves.",
"La dificultad depende de la media de tu plantilla y de tu prestigio. Cuanto más difícil, más te lo agradecerá la directiva.":"Difficulty depends on your squad's OVR and your reputation. The harder it is, the more the board will appreciate it.",
"La dificultad depende de tu media y de tu contrato con el club. Cuanto más difícil, mayor recompensa si lo cumples.":"Difficulty depends on your OVR and your contract with the club. The harder it is, the bigger the reward if you hit it.",
"La directiva abre la cartera, aunque te deja claro que quiere resultados ya.":"The board opens its wallet, but makes it clear it wants results now.",
"La directiva acepta tu condición. Os dan unas instalaciones de lujo.":"The board accepts your condition. You get luxury facilities.",
"La directiva anuncia que el club jugará la próxima temporada en un estadio nuevo, más moderno y más lejos del centro. La plantilla teme perder el calor de la grada.":"The board announces the club will play next season in a new stadium, more modern and further from the centre. The squad fears losing the warmth of the crowd.",
"La directiva aprieta y el vestuario está tocado. Dos buenos resultados seguidos la rebajan.":"The board is tightening the screws and the dressing room is hurting. Two good results in a row will ease it.",
"La directiva compra tu plan y te da margen. El vestuario lo nota.":"The board buys into your plan and gives you breathing room. The dressing room notices.",
"La directiva duda":"The board has doubts",
