"La directiva mueve ficha y el vestuario ve que el míster está de su lado.":"The board makes a move and the dressing room sees the manager is on their side.",
"La directiva no da su brazo a torcer y toma nota de tu desafío.":"The board won't budge and takes note of your defiance.",
