"La directiva quiere sacar a la sección femenina del estadio principal para que el césped llegue impecable a tus partidos. Las jugadoras te piden que des la cara por ellas.":"The board wants to move the women's team out of the main stadium so the pitch is immaculate for your matches. The players ask you to stand up for them.",
"La directiva quiere sacar a tu equipo del estadio principal para que el césped llegue impecable a los partidos de la sección masculina. Os mandarían a la ciudad deportiva.":"The board wants to move your team out of the main stadium so the pitch is immaculate for the men's team's matches. You'd be sent to the training ground.",
"La directiva rectifica. Tu postura se aplaude dentro y fuera del club.":"The board backs down. Your stance is applauded inside and outside the club.",
"La directiva sale sonriendo del sorteo: «Hay que aprovecharlo».":"The board leave the draw smiling: \"We have to make the most of it.\"",
"La directiva se cierra y el vestuario se queda con la sensación de que no sirve de nada.":"The board shuts down and the dressing room is left feeling it was all for nothing.",
"La directiva se enroca y te señala como cabecilla.":"The board digs in and singles you out as the ringleader.",
