"La directiva se levanta de la mesa. No hay acuerdo y el ambiente se enrarece.":"The board walks away from the table. No deal, and the atmosphere turns sour.",
"La directiva se sienta a negociar. Las primas mejoran y el vestuario sale más unido.":"The board sits down to negotiate. Bonuses improve and the dressing room comes out more united.",
"La directiva se siente chantajeada. La relación se enfría.":"The board feels blackmailed. The relationship cools.",
