"Les animas desde la sombra. Tu nombre no sale en los papeles.":"You cheer them on from the shadows. Your name stays off the paperwork.",
"Les cuento una cosa que no voy a decir en voz alta, pero {name} podría acabar en el {to}… si todo sale bien 🤫":"I'll tell you something I won't say out loud, but {name} could end up at {to}… if all goes well 🤫",
"Les digo que mañana, entrenamiento a las 7. El que no esté, que busque equipo.":"I tell them training is at 7 tomorrow. Anyone who isn't there can find another team.",
"Les digo que nadie nos regalará nada. Y que esta situación nos pertenece a todos, empezando por mí.":"I tell them nobody will give us anything. And that this situation belongs to all of us, starting with me.",
"Les digo que sonrían. Un equipo que sufre sin disfrutar ya ha perdido. Por lo menos disfrutemos.":"I tell them to smile. A team that suffers without enjoying has already lost. At least let's enjoy it.",
"Les dije que me siguieran o se fueran. Los que se queden estarán conmigo hasta el final, y punto.":"I told them to follow me or leave. Those who stay will be with me to the end, full stop.",
"Les echas de menos, pero te centras en el fútbol.":"You miss them, but you focus on football.",
