"Mal partido, sí. Pero un tropiezo no borra nada. Se volverá, como siempre se vuelve. 🤍":"Bad game, yes. But one slip erases nothing. We'll be back, like we always are. 🤍",
"Mal precedente.":"A bad precedent.",
