"Maradona marcó con la mano a Inglaterra en el Mundial 86 y Henry se ayudó de ella para dar el gol que llevó a Francia al Mundial 2010. Hoy el VAR lo pone casi imposible.":"Maradona scored with his hand against England at the 1986 World Cup and Henry used his to set up the goal that took France to the 2010 World Cup. Today VAR makes it almost impossible.",
