"Marca tu primer gol oficial.":"Score your first official goal.",
"Marca un golazo desde fuera del área.":"Score a screamer from outside the box.",
"Marca {name}. Bien. Ahora a mantener el resultado.":"{name} scores. Good. Now hold on to the lead.",
