"Marcas":"Score",
"Marcas diferencias. El seleccionador absoluto toma nota.":"You make a difference. The senior national team coach takes note.",
"Marcas en el minuto 110 el gol que mete a tu equipo en la siguiente ronda. El estadio estalla y el cuerpo te pide quitarte la camiseta y correr.":"In the 110th minute you score the goal that sends your team into the next round. The stadium erupts and your body is begging you to rip off your shirt and run.",
"Marcas en el último minuto, pero tras tres minutos de revisión el VAR anula tu gol por un fuera de juego de milímetros.":"You score in the last minute, but after three minutes of review VAR rules out your goal for an offside by millimetres.",
"Marcas tu penalti con sangre fría.":"You score your penalty with ice in your veins.",
"Marcas un golazo y la grada espera tu celebración. Te ronda la cabeza una voltereta, pero el césped está resbaladizo.":"You score a stunner and the crowd awaits your celebration. A backflip is on your mind, but the pitch is slippery.",
"Marcas y corres hacia su asiento. Tu madre llora en la grada.":"You score and run towards their seats. Your mum cries in the stands.",
"Marcas y cruzas el campo entero para celebrarlo delante de ellos. Tu afición te adora; la federación te multa.":"You score and sprint the whole length of the pitch to celebrate in front of them. Your fans adore you; the federation fines you.",
"Marcas y enseñas el mensaje. Tu grada enloquece; la rival te tendrá en su lista negra para siempre.":"You score and show the message. Your end goes wild; theirs will keep you on their blacklist forever.",
"Marcas y enseñas su nombre al mundo. Te cae una amarilla, pero nadie la recuerda: todos recuerdan el gesto.":"You score and show his name to the world. You pick up a yellow, but nobody remembers it: everyone remembers the gesture.",
"Marcas y levantas la camiseta: «¿Por qué siempre yo?». La foto da la vuelta al mundo.":"You score and lift your shirt: \"Why always me?\" The photo goes around the world.",
"Marcas y levantas las manos en señal de respeto. Ovación de las dos aficiones.":"You score and raise your hands in a show of respect. Both sets of fans applaud.",
"Marcas y lo celebras delante de ellos. Tu afición te lleva en volandas; la suya no te lo perdonará nunca.":"You score and celebrate right in front of them. Your fans carry you shoulder-high; theirs will never forgive you.",
