"Mayo de 2018: cinco días después de ganar su tercera Champions seguida, Zidane dimitió como entrenador del Real Madrid.":"May 2018: five days after winning his third Champions League in a row, Zidane resigned as Real Madrid manager.",
"Mayo de 2019: el Liverpool de Klopp remontó un 3-0 al Barcelona con una presión asfixiante en Anfield.":"May 2019: Klopp's Liverpool overturned a 3-0 first-leg deficit against Barcelona with suffocating pressing at Anfield.",
"Mayo de 2022: con su fichaje por el Real Madrid casi cerrado, Mbappé renovó por sorpresa con el PSG.":"May 2022: with his move to Real Madrid all but done, Mbappé surprisingly renewed with PSG.",
