"Menos minutos, más enseñanzas. Los jóvenes le adoran.":"Fewer minutes, more lessons. The youngsters adore him.",
"Menos opciones, pero el vestuario y la cantera lo agradecen":"Less chance, but the dressing room and the academy appreciate it",
"Menos riesgos, partidos cerrados y puntos que valen oro.":"Fewer risks, tight matches and points worth their weight in gold.",
"Menos taquilla por partido, más gente en la grada.":"Less gate money per match, more people in the stands.",
"Mensaje claro para todo el vestuario. Él lo encaja mal.":"A clear message to the whole dressing room. He takes it badly.",
"Mensaje de calma: partido a partido":"Message of calm: one game at a time",
"Mensaje sensato: nada de focos, a trabajar. El míster lo agradece.":"A sensible message: no spotlight, just work. The manager appreciates it.",
"Mensaje sobrio. Nadie se emociona, pero nadie te reprocha nada.":"A sober message. Nobody gets excited, but nobody holds anything against you.",
