"Nada de experimentos: la grada de siempre es vuestro mejor aliado.":"No experiments: your loyal crowd is your best ally.",
"Nada especial. Un rival más.":"Nothing special. Just another opponent.",
"Nada me sorprende. Sabía que aquí, con esta gente, los goles iban a llegar.":"Nothing surprises me. I knew that here, with these people, the goals would come.",
"Nada que no sintiera antes. El club me ha dado mucho, y sigo aquí. Bajar o no, seré del club hasta el final.":"Nothing I haven't felt before. The club has given me a lot, and I'm still here. Down or not, I'm with this club to the end.",
"Nada. Cosas del vestuario. Si nos peleamos es porque nos importa. Mañana nos damos un abrazo y listo.":"Nothing. Dressing room stuff. If we fight it's because we care. Tomorrow we hug it out and that's that.",
"Nada. El mismo equipo de siempre. Hoy salió todo. Pero que nadie se emocione, que esto es largo.":"Nothing. Same team as always. Today everything came off. But nobody get carried away, it's a long season.",
"Nada. Hay que seguir con lo mismo. Si cambio por una derrota, mañana perderé mi identidad, y ese es mi mayor activo.":"Nothing. We keep doing the same. If I change after one defeat, tomorrow I'll lose my identity, and that's my greatest asset.",
"Nada. Los grandes jugadores no necesitan que les digan nada. Hablamos con los goles.":"Nothing. Great players don't need to be told anything. We talk with goals.",
"Nada. Prefiero el silencio. A veces las palabras sobran y hay que dejar que hable el trabajo.":"Nothing. I prefer silence. Sometimes words are superfluous and you have to let the work do the talking.",
"Nada. Seguimos igual, con el mismo trabajo. A veces el fútbol te da lo que antes te quitó.":"Nothing. We carry on the same, with the same work. Sometimes football gives you back what it took away.",
"Nadie apostaba un euro por el {club} y vais líderes con el invierno ya pasado. El {bigClub} te tienta con un contrato mejor para el verano.":"Nobody gave {club} a prayer and you're top of the table with winter behind you. {bigClub} tempt you with a better contract for the summer.",
"Nadie en el banquillo puede jugar de {pos}.":"Nobody on the bench can play at {pos}.",
"Nadie ha preguntado por él ahora mismo.":"Nobody has asked about him right now.",
"Nadie habla y el ambiente se enrarece.":"Nobody talks and the atmosphere turns sour.",
"Nadie había visto al míster así. El equipo sale con otra cara.":"Nobody had seen the manager like this. The team comes out a different side.",
"Nadie la conoce, pero acaban todos coreando el estribillo.":"Nobody knows it, but they all end up singing along to the chorus.",
"Nadie la menciona en el vestuario. El grupo sigue a lo suyo.":"Nobody mentions it in the dressing room. The group stays focused.",
"Nadie lo ve. El gol sube al marcador.":"Nobody sees it. The goal stands.",
"Nadie me ha dicho nada. Me enteré por la prensa, como vosotros. Aquí hay mucho humo y poco fuego.":"Nobody has told me anything. I found out from the press, like you. Lots of smoke and little fire here.",
"Nadie nos regala nada. Nos han empatado porque no hemos sido letales. Y los letales ganan títulos.":"Nobody gives us anything. They held us because we weren't lethal. And lethal teams win titles.",
"Nadie olvidará lo que hizo {name} por nosotros. Estadio entero de pie 👏":"Nobody will forget what {name} did for us. The whole stadium on its feet 👏",
"Nadie os daba un duro y vais en la zona alta de la tabla. Se acerca el mercado de invierno y la directiva te pregunta si hace falta reforzarse para soñar.":"Nobody gave you a chance and you're near the top of the table. The winter window is approaching and the board asks whether you need reinforcements to dream.",
"Nadie pregunta. Tu cuenta engorda… de momento.":"Nobody asks questions. Your account grows fatter... for now.",
"Nadie puede pagarle":"Nobody can afford him",
"Nadie queda contento con la fórmula.":"Nobody is happy with the formula.",
"Nadie responde, pero la carta queda ahí y tu gesto se agradece.":"Nobody responds, but the letter is out there and your gesture is appreciated.",
"Nadie se atreve a romper la racha. El vestuario está más unido que nunca.":"Nobody dares break the streak. The dressing room is closer than ever.",
"Nadie se entera. El utillero se queda tranquilo y tú también.":"Nobody finds out. The kit man is at peace, and so are you.",
"Nadie se entera. Noche inolvidable.":"Nobody finds out. An unforgettable night.",
"Nadie se entera. Pero tú lo sabes.":"Nobody finds out. But you know.",
"Nadie se sorprende. El grupo funciona de memoria.":"Nobody is surprised. The group works from memory.",
"Nadie: / Absolutamente nadie: / {name} después de un gol: *celebración que parece un baile de bodas* 🕺":"Nobody: / Absolutely nobody: / {name} after a goal: *celebration that looks like a wedding dance* 🕺",
