"Nervios":"Nerves",
"Nervios los tengo yo, pero los jugadores están tranquilos. Es lo mejor que me ha pasado en esta semana.":"I'm the one with nerves, but the players are calm. That's the best thing that's happened to me all week.",
"Ni de broma. El árbitro tenía la tarjeta en la mano antes de la jugada.":"No way. The ref had the card in his hand before the challenge.",
"Ni el capitán consigue calmar los ánimos.":"Not even the captain can calm things down.",
"Ni entradas ni salidas en el último día.":"No arrivals or departures on the final day.",
"Ni especial ni nada. Ahora me debo a esta camiseta.":"Nothing special about it. I owe everything to this shirt now.",
"Ni excusas ni promesas. Solo trabajo.":"No excuses, no promises. Just work.",
"Ni le miras. Esa misma noche el club alaba tu templanza.":"You don't even look at him. That same night the club praises your composure.",
"Ni le miras. Profesionalidad.":"You don't even look at him. Professionalism.",
"Ni lo lees.":"You don't even read it.",
"Ni lo pienso. Un partido, solo uno. El del domingo es el más importante de mi vida.":"Not even thinking about it. One game, just one. Sunday's is the most important game of my life.",
"Ni lo sé ni me importa. Yo solo pienso en el domingo.":"I don't know and I don't care. I'm only thinking about Sunday.",
"Ni los rivales pueden con {name} hoy. Qué nivel 😮‍💨":"Not even the opposition can handle {name} today. What a level 😮‍💨",
"Ni más ni menos. Un punto es un punto. Y a quienes miran la tabla les diré: los puntos no se regalan.":"No more, no less. A point is a point. And to those looking at the table I say: nobody gives points away.",
"Ni se nota. Partidazo y el míster lo destaca en rueda de prensa.":"You'd never know. A great game and the manager singles you out at the press conference.",
"Ni subida ni bajada. Las peñas lo aceptan a regañadientes.":"No rise, no cut. The supporters' clubs grudgingly accept it.",
"Ni sustos ni regalos: el plato fuerte para {team} será {opp}":"No scares, no gifts: the big one for {team} will be {opp}",
"Ni tan mal, ¿eh? Cada día mejor. ¡A por todas, {club}! 🔥":"Not bad, eh? Better every day. Let's go, {club}! 🔥",
"Ni te lo planteas: el césped sigue siendo tu casa.":"You don't even think about it: the pitch is still your home.",
"Ni un remate claro.":"Not a single clear shot.",
"Ni una palabra":"Not a word",
"Ni una queja. Eres el primero en llegar y el último en irte. El cuerpo técnico lo nota.":"Not a single complaint. You're the first to arrive and the last to leave. The coaching staff notice.",
