"No quiso venir":"Wouldn't join",
"No renovar":"Don't renew",
"No se confíen: si se remonta, es porque el rival se relaja. No hay mérito.":"Don't get cocky: if you come back, it's because the opponent switched off. No merit.",
"No se cree tus promesas.":"He doesn't buy your promises.",
"No se escapa nada. Lo importante es mantener la calma y no mirar la clasificación. Nos quedan muchas balas.":"Nothing's slipping away. The key is to stay calm and not look at the table. We've got plenty of bullets left.",
"No se explica. Se acepta, se aprende y se sigue. No hay más secreto que ese. Mañana, a entrenar.":"You don't explain it. You accept it, learn and move on. There's no other secret. Tomorrow, training.",
