"Prefieres liderar con el ejemplo sin brazalete.":"You'd rather lead by example without the armband.",
"Prefieres no correr. El club toma nota de tu paciencia.":"You'd rather not rush. The club takes note of your patience.",
"Prefieres no mentir. La grada se queda con la duda.":"You'd rather not lie. The fans are left wondering.",
"Prefieres no mezclar. Sigues a lo tuyo.":"You'd rather not mix things. You keep to yourself.",
"Prefieres que hable el campo. Algunos fans se sienten solos.":"You'd rather let your football do the talking. Some fans feel left alone.",
"Prefieres que hable tu fútbol.":"You'd rather let your football do the talking.",
"Prefieres seguir en tu club, cerca de los tuyos. El club te lo agradece.":"You'd rather stay at your club, close to your loved ones. The club appreciates it.",
"Prefieres un año más con los chavales.":"You'd rather spend another year with the youngsters.",
"Prefiero no hablar. Cualquier cosa que diga me costará una multa y mi cuenta corriente no está para bromas.":"I prefer not to speak. Anything I say will cost me a fine and my bank account is in no mood for jokes.",
"Prefiero que hablen mis paradas.":"I'd rather let my saves do the talking.",
"Prefiero que me recuerden por mi nombre y por lo que gane.":"I'd rather be remembered by my name and what I win.",
