"Puede salir muy bien… o pesarle la camiseta.":"It could go brilliantly… or the shirt could weigh on him.",
"Puedes borrar cualquier partida desde «Cargar partida». Desinstalar la app elimina todo lo guardado en el dispositivo.":"You can delete any game from “Load game”. Uninstalling the app removes everything stored on the device.",
"Puedes borrar cualquier partida desde «Cargar partida». Desinstalar la app elimina todo lo guardado en el dispositivo. Para borrar los datos publicitarios que tiene Google, restablece tu ID de publicidad o entra en myadcenter.google.com.":"You can delete any game from “Load game”. Uninstalling the app removes everything stored on the device. To delete advertising data held by Google, reset your advertising ID or visit myadcenter.google.com.",
"Puedes borrar cualquier partida desde «Cargar partida». Si borras los datos de este sitio en tu navegador, se elimina todo lo guardado. Para borrar los datos publicitarios que tiene Google, entra en myadcenter.google.com.":"You can delete any save from “Load game”. Clearing this site's data in your browser removes everything saved. To delete the advertising data Google holds, go to myadcenter.google.com.",
"Puedes compaginarlo con el {club} o dejar el club y dedicarte en exclusiva.":"You can combine it with {club} or leave the club and focus on it full-time.",
"Puedes dejar el nombre en blanco si se le conoce por un solo nombre.":"You can leave the first name blank if he's known by a single name.",
"Puedes dirigir clubes de nivel {n} o menos; con más prestigio llegarán los grandes.":"You can manage clubs of level {n} or below; with more reputation the big ones will come calling.",
"Puedes empezar en cualquier club. Si ganas, llegarán ofertas de clubes más grandes.":"You can start at any club. If you win, offers from bigger clubs will come.",
"Puedes estudiar la lista, pero solo se ficha en verano (pretemporada) y en invierno (antes del tramo Feb–Mar).":"You can browse the list, but signings are only possible in summer (pre-season) and winter (before the Feb–Mar stage).",
"Puedes pedir el dorsal que quieras. Si lo lleva un compañero, quizá tengas que esperar a la próxima temporada.":"You can ask for any shirt number you want. If a teammate has it, you may have to wait until next season.",
"Puedes seguir en el fútbol desde el banquillo: eliges club, fichas, renuevas contratos, decides el once y cuidas la moral del vestuario.":"You can stay in football from the dugout: pick a club, sign players, renew contracts, choose the XI and look after dressing-room morale.",
"Puedes volver a dibujar o elegir la potencia":"You can redraw it or choose the power",
"Puerto Rico":"Puerto Rico",
"Pues habrá que ganar el domingo. Fácil de decir, ¿eh?":"Well, we'll just have to win on Sunday. Easy to say, eh?",
"Puesto":"Wearing",
"Pulsa el botón grande de abajo para avanzar al siguiente tramo de la temporada.":"Tap the big button at the bottom to move on to the next stage of the season.",
"Pulsa el botón grande de abajo. El juego avanza unas semanas y se para cuando hay algo que decidir.":"Tap the big button at the bottom. The game moves forward a few weeks and stops when there's something to decide.",
"Pulsa el botón grande de abajo. La temporada avanza unas semanas y se para cuando hay algo que decidir.":"Tap the big button at the bottom. The season moves forward a few weeks and stops when there's something to decide.",
"Pulsa «Corregir automáticamente» o cámbialo tú.":"Tap «Fix automatically» or change it yourself.",
"Pulsa ↺ junto a la velocidad para repetir la última jugada cuando quieras.":"Tap ↺ next to the speed controls to replay the last move whenever you want.",
"Punto débil: {w}.":"Weak spot: {w}.",
