"Seguirán formándose lejos de aquí.":"They'll keep developing elsewhere.",
"Seguirás siendo un portero de reflejos. El preparador no está convencido.":"You'll remain a reflex keeper. The coach isn't convinced.",
"Segunda Federación · Grupo 1":"Segunda Federación · Group 1",
