"Te acaban de expulsar. Camino del túnel, un aficionado rival baja hasta la valla y te dedica insultos muy graves.":"You've just been sent off. On your way down the tunnel, a rival fan comes down to the barrier and hurls vicious abuse at you.",
"Te acercas al fondo y la grada te canta el nombre.":"You head to the stand and the fans chant your name.",
"Te acompaña, crece contigo y mejora tu ánimo.":"Keeps you company, grows with you and lifts your mood.",
"Te acusan de abandonar el barco. Tu vuelta se hace incómoda.":"You're accused of abandoning ship. Your return is awkward.",
"Te acusan de poco patriota. Te pitan en un estadio.":"They accuse you of being unpatriotic. You're booed at a stadium.",
"Te acusan de ser el portavoz de la directiva.":"You're accused of being the board's mouthpiece.",
"Te adaptas de maravilla. Ganas versatilidad y el míster te adora.":"You adapt brilliantly. You gain versatility and the manager adores you.",
"Te agradece la lealtad y la relación se refuerza.":"He thanks you for your loyalty and your bond grows stronger.",
"Te alineas con el club. La directiva lo agradece y el vestuario se enfría.":"You side with the club. The board appreciates it and the dressing room cools.",
"Te alineas con la directiva. Dos días después el proyecto se hunde y tus palabras quedan ahí.":"You side with the board. Two days later the project collapses and your words are left hanging.",
"Te anticipas a todos: cabezazo picado y gol.":"You beat everyone to it: a downward header and goal.",
"Te apartas un tiempo para recuperar la cabeza.":"You step back for a while to clear your head.",
"Te arrastras por el campo y el míster te cambia al descanso.":"You drag yourself around the pitch and the manager subs you at half-time.",
"Te arreglarás con lo que tienes.":"You'll make do with what you have.",
"Te cambia el lado. Gol y a remar contra corriente.":"She switches sides. Goal, and now it's an uphill battle.",
"Te cargas el aductor de tanto repetir.":"You strain your adductor from so much repetition.",
"Te cierran el hueco y pierdes el balón.":"They close the gap and you lose the ball.",
"Te citan a declarar como testigo. Unas semanas de nervios.":"You're summoned to testify as a witness. A few nerve-racking weeks.",
"Te comunicas a gestos. Algunas instrucciones se pierden por el camino.":"You communicate by gestures. Some instructions get lost along the way.",
"Te convierten en meme y tus jugadores notan la presión.":"You become a meme and your players feel the pressure.",
"Te conviertes en un portero moderno. El juego del equipo lo agradece.":"You become a modern goalkeeper. The team's play benefits.",
