"Te frenan con falta en la frontal.":"You're brought down by a foul at the edge of the box.",
"Te gana la espalda un par de veces y marca. Duro día.":"He gets in behind you a couple of times and scores. Tough day.",
"Te ganas a la directiva, aunque algunos compañeros te miran mal.":"You win over the board, though some teammates give you dirty looks.",
"Te ganas a los pesos pesados.":"You win over the big names.",
"Te ganas la segunda amarilla. A la caseta.":"You earn a second yellow. Off you go.",
"Te ganas los pitos de todo el estadio y encima marca.":"You earn the whistles of the whole stadium and he scores anyway.",
"Te han destituido: busca nuevo club":"You've been sacked: find a new club",
"Te han hackeado la cuenta":"Your account's been hacked",
"Te han puesto un mote que escuece: «{nick}»":"You've been given a nickname that stings: “{nick}”",
"Te has convertido en meme":"You've become a meme",
"Te invitan a un partido benéfico para recaudar fondos para familias sin recursos. Es en tu día libre y el club no lo ve con buenos ojos por el riesgo de lesión.":"You're invited to a charity match to raise money for families in need. It's on your day off and the club frowns on it because of the injury risk.",
"Te irás libre en verano. Al club no le gustará.":"You'll leave for free in the summer. The club won't like it.",
"Te la da, pero los nervios te juegan una mala pasada.":"He gives it to you, but nerves get the better of you.",
"Te la roban y gol. El míster se lleva las manos a la cabeza.":"They steal it and score. The manager puts his hands on his head.",
"Te lanzan de todo, el partido se para y acabas fuera de ti. Tu peor tarde.":"They throw everything at you, the game stops and you lose it. Your worst afternoon.",
"Te llaman sobrevalorado":"They call you overrated",
"Te llueven las críticas por mal perdedor.":"You're hammered with criticism for being a sore loser.",
"Te lo guardas. Otra temporada más.":"You keep it to yourself. One more season.",
"Te lo has ganado. Ya te pondrás a tono en agosto.":"You've earned it. You'll get back in shape in August.",
"Te lo quedas.":"You keep him.",
"Te lo tomas como un reto. Entrenas a otro nivel.":"You take it as a challenge. You train on another level.",
"Te los devuelve en un año, con un abrazo y una cena.":"He pays you back within a year, with a hug and a dinner.",
"Te mides al {opp}, uno de tus antiguos clubes. ¿Es un partido especial?":"You're facing {opp}, one of your former clubs. Is it a special game?",
"Te niegas, perdéis la tanda y el club te multa con una semana de sueldo.":"You refuse, you lose the shootout and the club fines you a week's wages.",
"Te notas apagado":"You feel flat",
"Te perderás el partido.":"You'll miss the match.",
"Te pesa el ambiente y pasas el partido en una nube.":"The atmosphere weighs on you and you spend the match in a daze.",
"Te pierdes el partido, pero tu cuerpo te lo agradecerá.":"You miss the game, but your body will thank you.",
"Te pillan a 190 km/h. Portada de todos los periódicos.":"You get caught doing 190 km/h. Front page of every newspaper.",
"Te pillan las cámaras y la competición abre expediente: dos partidos de sanción y críticas por todas partes.":"The cameras catch you and the competition opens a disciplinary case: two-game ban and criticism all round.",
"Te pillan. Multa gorda y castigo sin jugar.":"You get caught. A hefty fine and a ban from playing.",
"Te pones a la defensiva y das más munición.":"You get defensive and give them more ammunition.",
"Te preguntará en cada partido si lo ves o lo simulas, en cualquier ritmo de decisiones.":"You'll be asked every match whether to watch or simulate, at any decision pace.",
"Te promete minutos en el próximo partido, aunque no le hace gracia.":"Promises you minutes in the next game, though not happily.",
"Te prometen fichajes y un proyecto ganador. Recuperas la ilusión.":"They promise signings and a winning project. Your enthusiasm returns.",
"Te proponemos jugadores útiles: mejoran a tu titular, están a su nivel o son recambios con proyección.":"We suggest useful players: they upgrade your starter, match their level or are backups with potential.",
"Te proponen organizar un campus de fútbol con tu nombre para niños de tu ciudad durante dos semanas de vacaciones.":"You're offered the chance to run a football camp in your name for kids in your city for two weeks of the holidays.",
"Te prueban en otra posición":"Trying you in another position",
"Te queda un año de contrato":"One year left on your contract",
"Te queda {n} cambio":"{n} sub left",
"Te quedan {n} cambios":"{n} subs left",
"Te quedas a centímetros y te llevas un golpe.":"You miss by inches and take a knock.",
"Te quedas en blanco a mitad de canción. Las risas duran toda la semana.":"You go blank halfway through the song. The laughter lasts all week.",
"Te quedas en el {club}":"You stay at {club}",
"Te quedas sin agente hasta que busques otro.":"You'll be without an agent until you find another.",
"Te quieren en un reality":"They want you on a reality show",
"Te quitas presión. El partido pasa sin pena ni gloria.":"You take the pressure off. The game passes without incident.",
"Te recibe un estadio lleno y una alfombra roja.":"A full stadium and a red carpet welcome you.",
"Te regatea y marca.":"He dribbles past you and scores.",
"Te relaja en casa: la forma aguanta mejor las malas rachas.":"Keeps you relaxed at home: your form holds up better through bad runs.",
"Te retiras.":"You retire.",
"Te retiras. Quizá en otro momento.":"You pull out. Maybe another time.",
"Te rozan en el área":"Contact in the box",
"Te sabes cada movimiento suyo y lo anulas por completo.":"You know his every move and shut him down completely.",
"Te saca a correr cada día: más físico y mejor ánimo.":"Takes you out running every day: better fitness and morale.",
"Te sacas el título de entrenador. Empiezas con {rep} de prestigio: cuanto más ganes, más grandes serán los clubes que te llamen.":"You earn your coaching badge. You start with {rep} reputation: the more you win, the bigger the clubs that will call.",
"Te sale redondo y te sientes mejor que nunca.":"It works perfectly and you feel better than ever.",
"Te sientan como un guante. La marca está encantada.":"They fit like a glove. The brand is delighted.",
"Te sientas ante los micrófonos.":"You sit down in front of the microphones.",
"Te sientas en la rueda de prensa previa y delante tienes dos latas de un refresco azucarado, patrocinador de la competición. Siempre has defendido comer sano.":"You sit down at the pre-match press conference and in front of you are two cans of a sugary soft drink, the competition's sponsor. You've always championed healthy eating.",
"Te sobra motivación, pero el ambiente se enrarece.":"Plenty of motivation, but the atmosphere turns sour.",
"Te suben el tope salarial.":"They raise your wage cap.",
"Te sumas al ataque":"Join the attack",
"Te supera con una vaselina.":"He lobs you with a chip.",
"Te toca bajo palos. Mira al lanzador a los ojos.":"Your turn in goal. Look the taker in the eye.",
"Te toca el {club}, muy superior sobre el papel. Tu cuerpo técnico está dividido: encerrarse atrás o jugarle de tú a tú.":"You've drawn {club}, far superior on paper. Your coaching staff is split: park the bus or take them on head-to-head.",
"Te toca. Coges el balón, lo besas y lo colocas en el punto.":"Your turn. You pick up the ball, kiss it and place it on the spot.",
"Te toman por un vendehúmos y el titular te perseguirá.":"They take you for a snake-oil salesman and the headline will haunt you.",
"Te trabas, pero la gente valora el esfuerzo. Te ganas a la ciudad.":"You stumble, but people value the effort. You win over the city.",
"Te tratas en una clínica puntera. Acortas plazos sin arriesgar.":"You get treated at a top clinic. You cut the timeline without taking risks.",
"Te vas cedido al {club}.":"You go on loan to {club}.",
