"Tendrás que elegir otro entrenador e indemnizarle.":"You'll have to choose another manager and pay compensation.",
"Tendré cuidado. El equipo me necesita en el campo, no en la grada.":"I'll be careful. The team needs me on the pitch, not in the stands.",
"Tenemos un dosier de cada lanzador. El mérito también es del preparador de porteros.":"We have a file on every penalty taker. The goalkeeping coach deserves credit too.",
"Tengo ganas de celebrarlo con toda la ciudad. Pero antes hay que ganar. Mientras, a descansar.":"I can't wait to celebrate with the whole city. But first we have to win. Meanwhile, rest.",
"Tengo la medalla de segundo en el cajón, al lado de las otras. Un día les haré compañía con una de oro.":"I've got the runner-up medal in the drawer, next to the others. One day a gold one will keep them company.",
"Tengo la sensación de que, aunque cambiara el once, el resultado sería el mismo. Es cuestión de actitud, no de nombres.":"I have the feeling that even if I changed the XI, the result would be the same. It's about attitude, not names.",
"Tengo la suerte de jugar con los mejores. Me rodeo de gente que me hace mejor. Y no leo las redes.":"I'm lucky to play with the best. I surround myself with people who make me better. And I don't read social media.",
"Tengo opinión, claro. Pero no la cuento a la prensa. Se la cuento a él, en su despacho, con la puerta cerrada.":"I have an opinion, of course. But I don't tell the press. I tell him, in his office, with the door closed.",
