"This is fine":"This is fine",
"Tiene derecho a estar enfadado. Pagan la entrada y esperan más. Le entiendo y prometo que lo compensaremos.":"He has every right to be angry. They pay for tickets and expect more. I get it, and I promise we'll make it up to them.",
"Tiene derecho a opinar. Respeto su sentimiento, pero el marcador está claro. Seguimos con lo nuestro.":"He's entitled to his opinion. I respect how he feels, but the scoreboard is clear. We carry on with our work.",
"Tienen razón. Fue un error, y pido perdón al club y a mis compañeros. Les prometo que no volverá a ocurrir.":"You're right. It was a mistake, and I apologise to the club and my teammates. I promise it won't happen again.",
"Tienes bastante con lo tuyo.":"You've got enough on your plate.",
"Tienes decisiones pendientes":"You have pending decisions",
"Tienes más de treinta años y el seleccionador te llama para otro gran torneo. En la prensa hay quien dice que deberías dejar paso a los jóvenes.":"You're over thirty and the national team manager calls you up for another major tournament. Some in the press say you should make way for the youngsters.",
