"Tienes otros compromisos.":"You have other commitments.",
"Tienes razón: daremos minutos a los que menos juegan.":"You're right: we'll give minutes to those who play less.",
"Tienes un partido grande en el calendario y el club propone moverlo al estadio más grande de la ciudad para batir vuestro récord de asistencia. Habrá más ingresos, pero perderéis vuestro campo de siempre.":"You have a big match on the calendar and the club proposes moving it to the city's biggest stadium to break your attendance record. More revenue, but you'll lose your usual ground.",
