"Titulares":"Headlines",
"Toca al jugador que quieres sacar. El partido se pausa mientras haces el cambio.":"Tap the player you want to take off. The match pauses while you make the sub.",
"Toca la zona a la que te vas a tirar":"Tap the zone you'll dive to",
