"Toca para abrir · desliza a la derecha para quitar":"Tap to open · swipe right to dismiss",
"Tocar y asegurar":"Keep it simple",
"Toda la plantilla se tira contigo. La grada te adopta al instante.":"The whole squad dives with you. The fans take you to their hearts instantly.",
"Todas las competiciones":"All competitions",
"Todas las cámaras te enfocan. ¿Qué respondes?":"Every camera is on you. What's your answer?",
"Todas las ligas":"All leagues",
"Todavía no has levantado ningún título.":"You haven't lifted a trophy yet.",
"Todavía no se habla de ti. Juega unos partidos y las redes empezarán a echar humo.":"Nobody's talking about you yet. Play a few games and social media will start buzzing.",
"Todavía no tienes partidas guardadas.":"You don't have any saved games yet.",
"Todavía te queda gasolina.":"You've still got fuel in the tank.",
"Todo el mundo da por hecho que en verano te irás gratis al {bigClub}. A última hora, el {club} te pone delante el contrato más alto de su historia y hasta voz en las decisiones deportivas.":"Everyone assumes you'll join {bigClub} for free in the summer. At the last minute, {club} put the biggest contract in their history in front of you, and even a say in sporting decisions.",
"Todo en regla, nada más. Ella lo nota.":"Everything by the book, nothing more. She notices.",
"Todo es mérito del cuerpo técnico, que me ha dado confianza.":"All the credit goes to the coaching staff for trusting me.",
"Todo listo para arrancar":"All set to kick off",
"Todo lo demás me da igual, pero el derbi no se pierde. ¡EL DERBI NO SE PIERDE!":"I don't care about anything else, but you don't lose the derby. YOU DON'T LOSE THE DERBY!",
"Todo queda en familia. Te sientes arropado y con los pies en el suelo.":"It all stays in the family. You feel supported and keep your feet on the ground.",
"Todo sale bien y cobras sin cansarte.":"It all goes well and you get paid without breaking a sweat.",
"Todo se cierra a las 23:58.":"It's all wrapped up at 11:58 pm.",
"Todo sigue como antes. Los más importantes se sienten valorados; los demás, menos.":"Everything stays the same. The key players feel valued; the rest, less so.",
"Todo. Y lo digo en serio. Desde esta noche vamos a replantearnos hasta la forma de calentar.":"Everything. And I mean it. From tonight we'll rethink everything, even how we warm up.",
"Todos":"All",
"Todos arriba, también el portero en los córners":"Everyone up, the keeper too on corners",
"Todos atrás y a la contra. Encajas mucho menos, sobre todo ante rivales mejores, pero creas poco.":"Everyone behind the ball and on the counter. You concede far less, especially against better sides, but create little.",
"Todos atrás y a la contra: pocos goles en las dos porterías.":"Everyone behind the ball and hit them on the break: few goals at either end.",
"Todos hemos tenido nuestra roja. A {name} le toca aprender y a nosotros, apoyar.":"We've all had our red card. {name} has to learn and we have to support.",
"Todos juntos con {name}. Recupérate sin prisas. Estarás de vuelta como una leyenda 💪":"All together with {name}. Take your time recovering. You'll be back a legend 💪",
"Todos son uno. Los suplentes se sienten parte del equipo.":"All for one. The subs feel part of the team.",
"Todos tenemos malos días. {name}, aquí estamos contigo. Mañana mejor 🤝":"We all have bad days. {name}, we're here with you. Better tomorrow 🤝",
"Todos tienen su día. Menos intensidad en liga, más unión.":"Everyone gets their day. Less intensity in the league, more unity.",
