"Treintaidosavos":"Round of 64",
"Tres cambios en el descuento y el reloj vuela.":"Three subs in stoppage time and the clock flies.",
"Tres canteranos más en la plantilla.":"Three more academy graduates in the squad.",
"Tres canteranos nuevos":"Three new academy graduates",
"Tres clubes de ligas menos potentes te ofrecen su banquillo. Gana allí y llamarán los grandes.":"Three clubs from smaller leagues offer you their dugout. Win there and the big clubs will call.",
"Tres clubes modestos quieren subirte de la cantera. Elige dónde debutar.":"Three modest clubs want to promote you from the academy. Choose where to make your debut.",
"Tres goles de {name}. Hay jugadores que juegan al fútbol. Y otros que lo escriben. 🎙️":"Three goals from {name}. Some players play football. Others write it. 🎙️",
"Tres goles en un abrir y cerrar de ojos y el partido es vuestro. Noche histórica.":"Three goals in the blink of an eye and the match is yours. A historic night.",
"Tres goles hoy. ¿Siente que es el mejor delantero de {lg}?":"Hat-trick today. Do you feel you're the best striker in {lg}?",
"Tres preguntas. Cada respuesta tiene consecuencias.":"Three questions. Every answer has consequences.",
"Tres preguntas. Verás el efecto de cada respuesta antes de elegir.":"Three questions. You'll see the effect of each answer before choosing.",
"Tres puntos más y a seguir. Ni tan mal, ¿eh? 😏 {score}":"Three more points and on we go. Not bad, eh? 😏 {score}",
"Tres puntos más. ¿Está satisfecho con el juego del equipo?":"Three more points. Are you happy with the team's play?",
"Tres semanas libres antes de la pretemporada. ¿Cómo las aprovechas?":"Three weeks off before pre-season. How do you spend them?",
"Tres semanas más de baja":"Three more weeks out",
"Tres. TRES. ¡¡TRES!! ¿Alguien más quiere hablar de {name}? ¿No? Pues eso 😎":"Three. THREE. THREE!! Anyone else want to talk about {name}? No? Thought so 😎",
"Triangulación de {a} y {b} por dentro.":"{a} and {b} triangulate through the middle.",
"Trinidad y Tobago":"Trinidad and Tobago",
"Tristeza y rabia. Pero aún queda un 1% de esperanza. Y con el 1% he ganado partidos, ahora a por la liga.":"Sadness and anger. But there's still 1% hope. I've won games with 1% before; now let's go for the league.",
