"Tu agente empieza a mover tu nombre. El club no lo ve con buenos ojos.":"Your agent starts shopping your name around. The club doesn't take it kindly.",
"Tu agente juega a dos bandas":"Your agent is playing both sides",
"Tu agente tiene dos propuestas sobre la mesa: una marca deportiva de primer nivel y una bebida energética que paga el doble.":"Your agent has two proposals on the table: a top sportswear brand and an energy drink that pays double.",
"Tu amigo de la infancia tiene problemas con su negocio y te pide 50 000 €. Te promete devolverlos.":"Your childhood friend is having trouble with his business and asks you for €50,000. He promises to pay it back.",
"Tu analista te enseña un informe: ganáis, pero el modelo dice que los resultados tienen más de suerte que de juego. Cree que deberías cambiar el plan.":"Your analyst shows you a report: you're winning, but the model says the results owe more to luck than to play. He thinks you should change the plan.",
"Tu aniversario de boda cae en plena semana de viaje con el equipo. En casa no están contentos.":"Your wedding anniversary falls in the middle of an away trip with the team. At home they're not happy.",
"Tu arrebato se convierte en grito de guerra para la grada.":"Your outburst becomes a battle cry for the fans.",
"Tu asiento vacío es la noticia de la noche. Tu afición te apoya; el resto del mundo, no tanto.":"Your empty seat is the story of the night. Your fans back you; the rest of the world, not so much.",
"Tu avatar":"Your avatar",
"Tu banquillo":"Your club",
"Tu banquillo está lleno de gente con ganas y poco protagonismo. Si alguno no ve minutos, el vestuario se resiente; si juegan todos, el once pierde equilibrio.":"Your bench is full of eager players with little game time. If some don't get minutes, the dressing room suffers; if everyone plays, the XI loses balance.",
"Tu bloqueo libera a tu compañero, que remata a placer.":"Your block frees up your teammate, who finishes at leisure.",
