"Tu crédito estaba bajo mínimos y el presidente ha decidido no despedirte… todavía. Necesitas una media de {need} puntos por partido de liga en el próximo tramo. Si lo consigues, la directiva vuelve a confiar en ti. ¿Cómo lo afrontas?":"Your credit had hit rock bottom and the chairman has decided not to sack you… yet. You need an average of {need} points per league game in the next stretch. Pull it off and the board will trust you again. How do you face it?",
"Tu cuerpo lo agradece desde la primera semana: menos fatiga y menos lesiones.":"Your body is grateful from the first week: less fatigue and fewer injuries.",
