"Tus partidos, fichajes y momentos clave":"Your matches, signings and key moments",
"Tus primas y tus condiciones son mucho peores que las de otras secciones del club y de la federación. Un grupo de compañeros prepara un escrito conjunto y te pide que lo firmes.":"Your bonuses and conditions are far worse than those of other sections of the club and the federation. A group of teammates is drafting a joint letter and asks you to sign it.",
"Tus rivalidades":"Your rivalries",
"Tus récords":"Your records",
"Tus vacaciones":"Your holidays",
"Tus vacaciones son para descansar.":"Your holidays are for resting.",
"Tutorial":"Tutorial",
"TÚ":"YOU",
"Táctica":"Tactics",
"Táctica y partido 2D":"Tactics and 2D match",
"Técnica":"Technique",
"Técnico de élite":"Elite Tactician",
"Tírate a tiempo: para la barra en la zona verde":"Dive on time: stop the bar in the green zone",
"Tít.":"Titles",
"Título: {t}":"Title: {t}",
"Títulos":"Titles",
"Tú":"You",
"Tú a lo tuyo: entrenar y jugar.":"You stick to your own business: train and play.",
"Tú decides":"Your call",
"Tú decides fichajes, precios de las entradas, obras y presupuesto.":"You decide signings, ticket prices, works and the budget.",
"Tú decides las alineaciones. El dueño no lo olvidará.":"You pick the line-ups. The owner won't forget it.",
