"¡ÚLTIMA HORA! {name} elige «{choice}». La mesa se divide. ¿Tú qué opinas? 📊":"BREAKING! {name} chooses \"{choice}\". The panel is split. What do you think? 📊",
"¡Última hora! {name} deja de ser entrenador. Lo veníamos avisando. 📺":"Breaking! {name} is no longer manager. We've been warning you. 📺",
"«Aquí decido yo». Hoy chupas banquillo.":"“I make the decisions here.” You're on the bench today.",
"«Aquí está nuestra historia». La grada te lo agradece.":"\"Our history is here.\" The fans are grateful.",
"«Aquí presiona todo el mundo». Te ganas una mirada fría.":"“Everyone presses here.” You get a cold stare.",
"«Aquí se gana entrenando»":"“Games are won on the training pitch”",
"«Aquí se viene aprendido». El jugador se hunde un poco más.":"\"You come here already knowing.\" The player sinks a bit further.",
"«Aquí se vive del domingo». Te escuchan, pero no te creen.":"“Here you live from Sunday to Sunday.” They listen, but don't believe you.",
"«Aquí tengo trabajo que acabar». La grada te aplaude.":"\"I've got work to finish here.\" The fans applaud you.",
"«Así no vamos a ningún sitio.» {name} sigue pidiendo {ask}.":"“This is going nowhere.” {name} still wants {ask}.",
"«Con el club, en las buenas y en las malas.» Te conviertes en un símbolo.":"\"With the club, through thick and thin.\" You become a symbol.",
"«Demuestra que eres el mejor»":"\"Show them you're the best\"",
"«El fútbol es de la gente». La grada corea tu nombre.":"“Football belongs to the people.” The stands chant your name.",
"«El fútbol es de la gente». Tu mensaje se convierte en bandera de la protesta.":"\"Football belongs to the people.\" Your message becomes the banner of the protest.",
"«El fútbol es suyo, no mío». Todo el mundo aplaude el gesto.":"«Football is hers, not mine». Everyone applauds the gesture.",
"«Ellos tienen más que perder». La calma se contagia.":"“They have more to lose.” The calm is contagious.",
"«Es normal querer jugar». Se acaba la polémica.":"“It's normal to want to play.” Controversy over.",
"«Es una señal de lo lejos que puede llegar este fútbol». Tu discurso se cita en todos los medios.":"\"It's a sign of how far this football can go.\" Your speech is quoted everywhere.",
"«Estamos juntos y saldremos de esta». Mensaje de capitán.":"“We're in this together and we'll get through it.” A captain's message.",
"«Estamos juntos». Quedas bien con casi todos.":"\"We're in this together.\" You keep almost everyone happy.",
"«Fue el corazón». Titular del día.":"“It was the heart.” Headline of the day.",
"«Gracias a cada compañero, a cada entrenador y a cada persona que alguna vez coreó mi nombre. Esto ha sido un sueño.»":"«Thank you to every teammate, every coach and every person who ever chanted my name. This has been a dream.»",
"«Hay cosas que no se compran». Ganas el respeto del vestuario y de la grada.":"\"Some things can't be bought.\" You earn the respect of the dressing room and the fans.",
"«Hoy cuelgo las botas, pero no me voy del fútbol. Lo mejor está por llegar.»":"«Today I hang up my boots, but I'm not leaving football. The best is yet to come.»",
"«Hoy he estado mal y lo siento». La honestidad cae bien.":"“I was poor today and I'm sorry.” Honesty goes down well.",
"«Los resultados llegarán». La directiva te respalda; la grada, a medias.":"“The results will come.” The board backs you; the stands, half-heartedly.",
"«Me voy antes de que el balón empiece a correr más que yo. Nos vemos en la grada… o en el banquillo.»":"«I'm leaving before the ball starts running faster than me. See you in the stands… or on the bench.»",
"«Mi trabajo es el campo». El vestuario no se contagia.":"\"My job is on the pitch.\" The dressing room stays unaffected.",
"«Más» → «Editor de la partida»: cambia nombres, abreviaturas y colores de clubes, y nombres de ligas y copas.":"«More» → «Game editor»: change club names, abbreviations and colours, and league and cup names.",
"«No se gana nada con niños»":"\"You can't win anything with kids\"",
"«No se vende». El vestuario y la grada te lo agradecen.":"\"He's not for sale.\" The dressing room and the fans are grateful.",
"«Nuestro objetivo es otro». La directiva respira, la grada no tanto.":"“Our goal is something else.” The board breathes easy, the fans less so.",
"«O la estrella o nada». No hay dinero.":"“Either the star or nothing.” There's no money.",
"«Partido a partido»":"“One game at a time”",
"«Sal a calentar»":"\"Go and warm up\"",
"«Salid y disfrutad»":"“Go out and enjoy it”",
"«Sangre fría»: +2 en Tiro (Colocación si eres portero) y la forma cae más despacio tras un mal partido.":"\"Ice in your veins\": +2 Shooting (Positioning if you're a keeper) and your form drops more slowly after a bad game.",
"«Si nos hicieron cuatro, podemos hacer seis»":"“If they scored four, we can score six”",
"«Tienen derecho a quejarse». La grada te adopta y el palco se enfada.":"\"They have the right to complain.\" The fans adopt you and the directors' box is furious.",
"«Una cosa no tiene que ver con la otra». Te quedas sin lo uno ni lo otro.":"\"One thing has nothing to do with the other.\" You end up with neither.",
"«Vamos a por la liga»":"“We're going for the league”",
"«Vengo a ganar». La grada te adopta antes de pisar el césped.":"\"I'm here to win.\" The fans adopt you before you've set foot on the pitch.",
"«Yo estoy para decidir partidos, no para correr». Se ofende.":"“I'm here to win games, not to run.” He's offended.",
"«{answer}»":"\"{answer}\"",
