"«{choice}». Lo que hay que ver. {name} no da una.":"\"{choice}\". Unbelievable. {name} can't get anything right.",
"«{choice}». Se puede discutir. Pero {name} decide con argumentos, y eso no abunda. ✒️":"“{choice}”. It's debatable. But {name} decides with arguments, and that's rare. ✒️",
"«{choice}»… Jajaja. Gracias, {name}, por facilitarnos el trabajo 😅":"\"{choice}\"… Hahaha. Thanks, {name}, for making our job easier 😅",
"«{choice}»… Veremos cómo sale. Hay que dar tiempo a las decisiones.":"\"{choice}\"… We'll see how it turns out. Decisions need time.",
"«{nick}» lo vuelve a hacer: ¡qué parada de {k}!":"“{nick}” does it again: what a save by {k}!",
"«{quote}»":"\"{quote}\"",
"«{quote}» — {name}. Interesting.":"\"{quote}\" — {name}. Interesting.",
"«{quote}». Eso, {name}. Con un par. Así se habla 👏":"\"{quote}\". That's it, {name}. Guts. That's how you talk 👏",
"«{quote}». Frase de {name} que dejará huella en la historia del fútbol (o no) 📜":"\"{quote}\". A line from {name} that will go down in football history (or not) 📜",
"«{quote}». Lo ha dicho {name}. Y yo, que llevo años en esto, no lo había oído nunca así. 🌙":"“{quote}”. {name} said it. And I, after years in this business, had never heard it put like that. 🌙",
"«{quote}». Muy bonito, {name}. Pero el fútbol se juega en la cancha, no en el micrófono. 🌶️":"“{quote}”. Very nice, {name}. But football is played on the pitch, not at the microphone. 🌶️",
"«{quote}». Se podía haber ahorrado la rueda de prensa entera.":"\"{quote}\". They could have skipped the whole press conference.",
"«{quote}». Sin más. Hablar es fácil, ahora a demostrarlo en el campo.":"\"{quote}\". That's all. Talk is cheap, now prove it on the pitch.",
"«{quote}». {name} ha incendiado la sala de prensa. Mañana, portadas 🔥📰":"“{quote}”. {name} has set the press room on fire. Tomorrow's front pages sorted 🔥📰",
"«{quote}»: palabras de {name}. Eso mismo queríamos que dijese antes del partido 😏":"\"{quote}\": {name}'s words. Exactly what we wanted to hear before the game 😏",
"«{quote}»… ¿Qué dice {name}? Cuanto menos hable, mejor.":"\"{quote}\"… What is {name} on about? The less they say, the better.",
"«¡Esto no se nos escapa!»":"\"We're not letting this slip!\"",
