"¿Cómo planteas el partido?":"How do you set up the game?",
"¿Cómo se va a llamar?":"What will you call it?",
"¿Debut de {name}? Espero que no sea un error. Tengo mis dudas, sinceramente.":"{name} debuting? I hope it's not a mistake. I have my doubts, honestly.",
"¿Dejar la selección?":"Quit the national team?",
"¿Derbi? Para mí son tres puntos como otros cualquiera.":"Derby? To me it's three points like any other.",
"¿Dividido? Si lo estuviera, lo sabría. Solo sé que tengo 25 jugadores y todos quieren jugar. Ese es el problema.":"Divided? If it were, I'd know. All I know is I have 25 players and they all want to play. That's the problem.",
"¿Dónde juega?":"Where do they play?",
"¿En qué vais a trabajar este verano? Marcará toda la temporada.":"What will you work on this summer? It'll shape the whole season.",
"¿En qué vas a trabajar esta temporada? Esto es lo que te subirá al terminarla.":"What will you work on this season? This is what will improve when it ends.",
"¿Era el culpable {name}? Para mí, una parte. La otra está en los despachos. 🌶️":"Was {name} to blame? Partly, for me. The rest is upstairs in the boardroom. 🌶️",
"¿Esa es su pregunta? ¿Después de noventa minutos de partido? Siguiente pregunta, por favor.":"That's your question? After ninety minutes of football? Next question, please.",
"¿Esa foto? No salgo ni de lejos bien parado. Debería haberme puesto el otro pantalón. Eso sí que me preocupa.":"That photo? I don't come out of it well at all. Should've worn the other trousers. Now that does worry me.",
