"¿Irte en lo más alto?":"Leave at the top?",
"¿Merecían más? Parece que tuvieron mejores ocasiones.":"Did you deserve more? You seemed to have the better chances.",
"¿Mudamos el partido al estadio grande?":"Move the match to the big stadium?",
